window.YIHU_FACULTY=[{"id":"AL01","kind":"AL","title":"被告人吴某涛诈骗案——依法惩处线下取款配合实施AI拟声诈骗的人员","summary":"本案是利用AI拟声技术冒充孙子，制造紧急场景诈骗老年人的典型案例","sections":[{"heading":"事实经过","text":"2025年4月下旬，被告人吴某涛经人介绍，获悉可前往各地帮助收取诈骗资金以牟取非法利益，遂添加上线联系方式。之后，吴某涛按照上线指令，乘车前往湖北省黄石市，假冒身份上门收取诈骗款。吴某涛来到被害人家后，当场拨通上线语音电话，再由上线利用AI拟声技术模拟被害人亲属声音，冒充亲属取得信任，从三名老人处骗取现金共计6万元，后将上述款项交给他人，从中获利1700元。\n争议或侵权的问题：诈骗分子利用AI技术冒充亲属骗取信任，侵害老年人财产权。"},{"heading":"实际处理过程及结果","text":"本案经湖北省黄石市黄石港区人民法院审理，现已发生法律效力。法院认为，被告人吴某涛以非法占有为目的，伙同他人骗取财物，数额巨大，其行为已构成诈骗罪。吴某涛明知他人实施诈骗，仍接受上线安排上门收取、转移诈骗款，为上线获得诈骗款提供帮助，构成诈骗罪共犯，在共同犯罪中系从犯。吴某涛到案后坦白罪行，在法院审理阶段全部退赔并取得被害人谅解，依法对其减轻处罚，以诈骗罪对其判处有期徒刑二年一个月，并处罚金。"},{"heading":"对老人的实用提醒","text":"1.接到亲属要求转账的电话，先挂断并回拨核实；或者通过微信、短信等方式与亲属核实；\n2.遇陌生人上门代收钱款，拒绝并立即报警；\n3.不向陌生人透露银行卡密码、验证码。"},{"heading":"与其他案件不能直接类比的条件","text":"本案存在该案具有AI技术手段和线下取款特征，与普通电话诈骗在行为方式上有差异。"},{"heading":"可类比的情形","text":"例如他人利用ai声音直接要求线上转账；他人谎称自己是亲人的朋友，声称亲人有事让朋友上门取钱等情形。"}],"images":[{"src":"assets/faculty/AL01-1.webp","alt":"被告人吴某涛诈骗案——依法惩处线下取款配合实施AI拟声诈骗的人员配图 1","credit":"情景示意"}],"quiz":null,"source":"https://www.court.gov.cn/zixun/xiangqing/490051.html","sourceName":"最高人民法院","author":"林泽宇","reviewer":"鄢凡翕","reviewStatus":"已审核","approvalBasis":"项目负责人于2026-10-15确认全部审核完成","sourceSha256":"fa13419314958e245ed4073ca0aee2e3f0c82e3ed22414d4f0c04bbcd6bc60cf"},{"id":"AL02","kind":"AL","title":"王某某诉兴业银行股份有限公司北京东外支行金融委托理财合同纠纷案","summary":"本案是老年人线下购买高风险理财产品时，金融机构采取用老人手机帮忙处理以逃避“双录”监管案例","sections":[{"heading":"事实经过","text":"王某某（满65周岁）在兴业银行股份有限公司北京东外支行客户经理推介下，先后认购三只基金共计106万元，赎回时亏损219,586.34元。王某某主张其购买与风险测评由客户经理代为操作且未对购买过程进行“双录”（录音录像），兴业银行辩称上述购买行为均为王某某自行线上操作，线上销售不适用线下“双录”监管规定。"},{"heading":"争议或侵权问题","text":"银行是否履行了“适当性义务”和“双录义务”，是否应为老年投资者的亏损承担赔偿责任。"},{"heading":"实际处理过程及结果","text":"法院认定兴业银行对老年客户履行适当性义务存在瑕疵，并存在“线下营销推介、线上完成交易”以规避“双录”监管，明显超出消费者自主购买范畴的情形，一审法院判令银行对王某某投资损失承担30%赔偿责任，赔付63,031.05元。二审维持原判。"},{"heading":"对老人的实用提醒","text":"不将手机、账户密码交给他人操作；\n购买理财前问清产品风险等级以及产品费用等相关产品信息；\n不轻信“保本高息”宣传；\n购买理财产品以及贵重物品时及时录音录像保存证据。"},{"heading":"与其他案件不能直接类比的条件","text":"该案涉及高风险理财产品和银行代客操作，与银行存款纠纷、证券投资纠纷适用规则不同。"},{"heading":"可类比的情形","text":"购买高价理财产品等"}],"images":[{"src":"assets/faculty/AL02-1.webp","alt":"王某某诉兴业银行股份有限公司北京东外支行金融委托理财合同纠纷案配图 1","credit":"情景示意"}],"quiz":null,"source":"https://cca.org.cn/single/11179/63166.html","sourceName":"中国消费者协会","author":"林泽宇","reviewer":"鄢凡翕","reviewStatus":"已审核","approvalBasis":"项目负责人于2026-10-15确认全部审核完成","sourceSha256":"6e0d2dabfa831dcbcc4739db24c740fda80cdd4af2a6da4558dfbc72af189f11"},{"id":"AL03","kind":"AL","title":"孙某某诉赵某某产品责任纠纷案——经营者虚假宣传理疗产品功能，应当退一赔三","summary":"本案是保健品广告虚假宣传，误导消费者的典型案例","sections":[{"heading":"事实经过","text":"赵某某在网络平台宣传某理疗产品具有“降三高”“治疗糖尿病并发症”等功效。孙某某（60岁）看到后至赵某某经营的理疗店体验，并与赵某某签订《调理合同》，购买了10个疗程的理疗项目，总价1万余元。理疗过程中，理疗店仅使用普通的护肤品进行理疗服务。4个疗程后并无效果，孙某某与赵某某协商退款未果。孙某某诉至法院，请求判令赵某某退还支付的理疗费1万余元并承担三倍价款的惩罚性赔偿责任。\n争议或侵权的问题：经营者对老年消费者的虚假宣传是否构成欺诈，老年人能否主张惩罚性赔偿。"},{"heading":"实际处理过程及结果","text":"审理法院认为，经营者向消费者提供有关商品或者服务的信息应当真实、全面，不得作虚假或者引人误解的宣传。根据《中华人民共和国消费者权益保护法》第五十五条规定，经营者提供商品或者服务有欺诈行为的，应当按照消费者的要求增加赔偿其受到的损失，增加赔偿的金额为消费者购买商品价款或者接受服务费用的三倍。本案中，赵某某虚假宣传其理疗产品有“降三高”等治病功能，夸大功效，诱导老年人消费，构成欺诈，应当退款并承担惩罚性赔偿责任。最终判决：赵某某退还孙某某理疗费1万余元并支付三倍价款的惩罚性赔偿金3万余元。"},{"heading":"对老人的实用提醒","text":"保健品不能替代药品，治病需要到正规医院；\n对声称“包治百病”的产品保持警惕；\n购买高价商品前与子女商量，并保存好宣传材料作为维权证据。"},{"heading":"与其他案件不能直接类比的条件","text":"该案涉及“伪科学”疗效宣传和老年人健康诉求，与普通商品质量纠纷在欺诈认定标准上存在差异。"}],"images":[{"src":"assets/faculty/AL03-1.webp","alt":"孙某某诉赵某某产品责任纠纷案——经营者虚假宣传理疗产品功能，应当退一赔三配图 1","credit":"情景示意"}],"quiz":null,"source":"https://www.court.gov.cn/zixun/xiangqing/494701.html","sourceName":"最高人民法院","author":"林泽宇","reviewer":"鄢凡翕","reviewStatus":"已审核","approvalBasis":"项目负责人于2026-10-15确认全部审核完成","sourceSha256":"3a683f68f7490c2422128abe0bbeea90acccdf925c5c198f5d5feea3bfbd5b54"},{"id":"KT01","kind":"KT","title":"冒充客服退款诈骗","summary":"骗子冒充电商客服以商品质量问题、订单异常为由主动提出退款赔偿，诱导受害人点击陌生链接、泄露银行卡信息或转账实施诈骗，退款务必通过官方平台核实。","sections":[{"heading":"场景开头","text":"退休的王阿姨在家接到陌生来电，对方自称电商平台客服，精准报出她近期的网购订单、收货地址，称她购买的日用品存在质量问题，要办理双倍退款赔偿。王阿姨见对方对购物信息一清二楚，便放下戒心，准备按对方指引操作。"},{"heading":"骗子常说的话","text":"“您购买的商品有质量问题，我们给您双倍退款，点这个链接填银行卡信息就能到账。” “您的退款账户被冻结了，转一笔验证金解冻后，钱会和退款一起返还。”"},{"heading":"危险信号","text":"陌生来电主动提出退款，且能准确说出个人完整订单信息\n诱导点击陌生链接、扫码，或要求下载非官方 APP\n以 “解冻”“验证” 为由，索要银行卡号、短信验证码或要求转账"},{"heading":"现在可以做的事","text":"立刻挂断陌生来电，不点击对方发送的任何链接、不扫码。\n打开官方购物 APP，通过平台内置客服入口核实订单退款事宜。\n无法辨别真伪时，拨打 96110 反诈专线咨询确认。"},{"heading":"遇到紧急情况时怎么处理","text":"若已经泄露银行卡信息、验证码或不慎转账，第一时间拨打 110 报警，同步联系银行冻结账户、止付交易，留存好通话、转账等全部证据。"}],"images":[{"src":"assets/faculty/KT01-1.webp","alt":"冒充客服退款诈骗配图 1","credit":"情景示意"},{"src":"assets/faculty/KT01-2.webp","alt":"冒充客服退款诈骗配图 2","credit":"情景示意"},{"src":"assets/faculty/KT01-3.webp","alt":"冒充客服退款诈骗配图 3","credit":"情景示意"},{"src":"assets/faculty/KT01-4.webp","alt":"冒充客服退款诈骗配图 4","credit":"情景示意"}],"quiz":{"question":"接到自称电商客服的电话，称商品有问题要退款，还发来陌生链接，正确做法是？","choices":["点击链接填信息，尽快拿到退款 ","挂断电话，去官方购物平台找客服核实"],"answer":1,"explain":"选 B。正规电商退款只会通过官方渠道原路返还，不会私下发链接索要银行卡号、验证码，更不会要求转账解冻，遇到主动退款务必通过官方渠道核实。"},"source":"","sourceName":"无","author":"王皓","reviewer":"鄢凡翕","reviewStatus":"已审核","approvalBasis":"项目负责人于2026-10-15确认全部审核完成","sourceSha256":"a34166a7f7f88dfa568c4808b9773feac620bddf98a4e0765c0b72551cd17804"},{"id":"KT02","kind":"KT","title":"养老理财“保本高收益”","summary":"骗子冒充金融机构工作人员，以 “代理退保 + 保本高收益养老理财” 为诱饵，诱导老年人退保转账至虚假平台实施诈骗，养老投资理财需通过正规金融渠道办理。","sections":[{"heading":"场景开头","text":"退休的张阿姨接到自称 “金融服务中心” 的陌生来电，对方精准报出她的保险保单详情，称原有保险收益低、保障不足，可帮她办理全额退保，转投年化 8%-10% 的保本养老理财，还附赠体检、旅游权益，张阿姨渐渐动了心。"},{"heading":"骗子常说的话","text":"“您原来的保险收益太低了，我们帮您全额退保，转投保本高息的养老理财，年化收益能到 10%。” “办理就送免费体检和旅游名额，签了代理协议马上就能办手续。”"},{"heading":"危险信号","text":"陌生来电自称金融机构人员，主动劝说退保并推荐高收益养老理财\n承诺保本高息，还以体检、旅游等额外福利吸引老年人\n诱导签署代理协议、下载非官方 APP 转入资金"},{"heading":"现在可以做的事","text":"立刻挂断陌生推销电话，不签署任何代理退保或理财协议。\n拨打保险公司官方客服热线，核实保单收益与正规退保流程。\n拿不准时拨打 96110 反诈专线或向金融监管部门咨询核实。"},{"heading":"遇到紧急情况时怎么处理","text":"若已经办理退保、转账投入虚假理财平台，立即拨打 110 报警，留存通话记录、协议文件与转账凭证，同步联系保险公司核查止损。"}],"images":[{"src":"assets/faculty/KT02-1.webp","alt":"养老理财 “保本高收益配图 1","credit":"情景示意"},{"src":"assets/faculty/KT02-2.webp","alt":"养老理财 “保本高收益配图 2","credit":"情景示意"},{"src":"assets/faculty/KT02-3.webp","alt":"养老理财 “保本高收益配图 3","credit":"情景示意"},{"src":"assets/faculty/KT02-4.webp","alt":"养老理财 “保本高收益配图 4","credit":"情景示意"}],"quiz":{"question":"接到自称金融服务中心的电话，劝说你把保险退保转投 “保本高息” 养老理财，还送体检旅游，正确做法是？","choices":["赶紧签协议办理，抓住高收益的好机会 ","挂断电话，拨打保险公司官方客服核实"],"answer":1,"explain":"选 B。正规金融产品不会承诺 “保本高息”，陌生来电主动劝说退保转理财多为诈骗，务必通过官方渠道核实，切勿随意签署协议、转账投钱。"},"source":"","sourceName":"无","author":"王皓","reviewer":"鄢凡翕","reviewStatus":"已审核","approvalBasis":"项目负责人于2026-10-15确认全部审核完成","sourceSha256":"3d74041cd2f92c9385dadf48faeefdabc381edc5a040edb848f770906e23fe66"},{"id":"KT03","kind":"KT","title":"冒充公检法要求转账","summary":"骗子冒充公检法人员，以当事人涉嫌犯罪为由制造恐慌，诱导其转入 “安全账户” 实施诈骗；公检法不会电话办案，更不会要求转账汇款。作者:王皓","sections":[{"heading":"场景开头","text":"李阿姨接到一个陌生电话，对方自称是公安局民警或检察院工作人员，说她的身份信息被涉嫌洗钱案件冒用，要求她配合调查。对方还能准确说出李阿姨的姓名、身份证号和住址，让她先把银行卡里的钱转入 “安全账户” 核验资金来源，调查结束后再原路退回。"},{"heading":"骗子常说的话","text":"“你的身份证被人冒用，涉嫌一起重大洗钱案件，现在需要你配合公安调查。” “把钱转到我们的安全账户核验，证明资金合法，调查完马上退给你。”"},{"heading":"危险信号","text":"陌生来电自称公检法人员，还能说出个人身份信息\n以 “涉嫌犯罪”“配合调查” 为由制造紧张和恐惧\n要求转账到 “安全账户”，或让当事人离开家人独自操作"},{"heading":"现在可以做的事","text":"立即挂断电话，不转账、不透露验证码，也不下载对方提供的软件。\n通过官方渠道拨打当地公安局或检察院电话核实身份和案件。\n发现被骗后立即拨打 96110 或 110 报警，联系银行止付。"},{"heading":"遇到紧急情况时怎么处理","text":"如果已经转账，立即拨打 110 报警，同时联系银行冻结账户、止付交易，保存通话记录、短信、转账凭证和对方账号信息。"}],"images":[{"src":"assets/faculty/KT03-1.webp","alt":"冒充公检法要求转账配图 1","credit":"情景示意"},{"src":"assets/faculty/KT03-2.webp","alt":"冒充公检法要求转账配图 2","credit":"情景示意"},{"src":"assets/faculty/KT03-3.webp","alt":"冒充公检法要求转账配图 3","credit":"情景示意"},{"src":"assets/faculty/KT03-4.webp","alt":"冒充公检法要求转账配图 4","credit":"情景示意"}],"quiz":{"question":"接到自称公检法人员电话，说你涉嫌犯罪并要求转入 “安全账户”，应该怎么做？","choices":["按对方要求尽快转账，证明自己清白 ","挂断电话，通过官方渠道核实，坚决不转账"],"answer":1,"explain":"选 B。真正的公检法机关不会通过电话办案，也不会要求当事人把钱转入所谓 “安全账户”。遇到此类电话，应立即挂断并通过官方渠道核实。"},"source":"","sourceName":"无","author":"","reviewer":"鄢凡翕","reviewStatus":"已审核","approvalBasis":"项目负责人于2026-10-15确认全部审核完成","sourceSha256":"1479a604f36beb0b870390af2f5df05cb6719e677005e5b9a7ad42901e06bfa0"},{"id":"KT04","kind":"KT","title":"保健品与免费礼品诱导购买","summary":"骗子以免费礼品、免费健康讲座为诱饵，夸大保健品疗效，诱导老年人高价购买；保健品不能替代药品，购买前应与家人商量并通过正规渠道核实。","sections":[{"heading":"场景开头","text":"王阿姨在社区广场参加免费健康讲座，对方免费赠送鸡蛋、毛巾、体检券，还现场 “专家” 推荐具有 “降压、降糖、提高免疫力” 等神奇功效的保健品，不少老人在旁起哄购买。"},{"heading":"骗子常说的话","text":"“今天免费领礼品，买保健品还能享受补贴。” “这个产品能辅助降压降糖，很多老人吃了都说好。” “今天下单最优惠，明天就恢复原价。”"},{"heading":"危险信号","text":"以免费礼品、免费体检、讲座送礼吸引老人到场\n夸大保健品功效，宣称能治病、降压降糖或替代药物\n现场起哄、限时优惠、诱导大量购买"},{"heading":"现在可以做的事","text":"不轻信 “包治百病”“神奇疗效” 的保健品宣传。\n不被免费礼品牵着走，购买前先和子女、医生商量。\n通过正规药店、医院或官方渠道核实产品信息。"},{"heading":"遇到紧急情况时怎么处理","text":"发现被骗后，立即停止付款，保存宣传资料、收据、转账记录和对方联系方式，拨打 12315 或 96110 咨询；若已购买大量产品，尽快联系商家退货并向市场监管部门反映。"}],"images":[{"src":"assets/faculty/KT04-1.webp","alt":"保健品与免费礼品诱导购买配图 1","credit":"情景示意"},{"src":"assets/faculty/KT04-2.webp","alt":"保健品与免费礼品诱导购买配图 2","credit":"情景示意"},{"src":"assets/faculty/KT04-3.webp","alt":"保健品与免费礼品诱导购买配图 3","credit":"情景示意"},{"src":"assets/faculty/KT04-4.webp","alt":"保健品与免费礼品诱导购买配图 4","credit":"情景示意"}],"quiz":{"question":"参加免费健康讲座，对方送鸡蛋并推荐能 “降压降糖” 的保健品，正确做法是？","choices":["现场赶紧购买，还能领礼品 ","先别买，和子女商量并核实产品信息"],"answer":1,"explain":"选 B。保健品不是药品，不能替代药物治疗；以免费礼品诱导购买并夸大疗效，属于常见养老诈骗套路。购买前应核实产品信息，并与家人商量。"},"source":"","sourceName":"无","author":"王皓","reviewer":"鄢凡翕","reviewStatus":"已审核","approvalBasis":"项目负责人于2026-10-15确认全部审核完成","sourceSha256":"101acf8709721aa682aa80870b084f89dc8b989db5c0dc631a7b9145a21232a1"},{"id":"KT05","kind":"KT","title":"陌生链接、屏幕共享和远程控制","summary":"骗子以退款、账户安全为由，诱导受害人点击陌生链接、开启屏幕共享和远程控制，窃取银行卡信息并转移资金；切勿点击陌生链接，不随意开启屏幕共享和远程权限。","sections":[{"heading":"场景开头","text":"退休的周师傅接到自称电商客服的来电，称其购买的家电存在质量问题要办理双倍退款。对方发来一条陌生链接，还要求周师傅开启手机屏幕共享，说要远程指导他填写退款信息，周师傅见对方说得详细，准备按指引操作。"},{"heading":"骗子常说的话","text":"“您点这个链接填退款信息，开启屏幕共享我一步步教您操作，几分钟就能到账。” “您的账户有安全风险，下载这个安全 APP 开启远程保护，资金就不会出问题。”"},{"heading":"危险信号","text":"发送陌生链接、二维码，诱导下载非官方 APP\n以协助办理业务为由，要求开启屏幕共享、远程控制权限\n全程引导操作，索要银行卡号、验证码等敏感信息"},{"heading":"现在可以做的事","text":"立刻挂断电话，不点击陌生链接，不开启屏幕共享和远程权限。\n打开对应官方平台 APP，通过内置客服入口核实业务真实情况。\n无法辨别真伪时，拨打 96110 反诈专线咨询确认。"},{"heading":"遇到紧急情况时怎么处理","text":"若已点击链接、开启共享或泄露敏感信息，立即断开网络、拔出手机卡，修改支付账户与银行卡密码并冻结账户，第一时间拨打 110 报警，留存好通话与操作记录。"}],"images":[{"src":"assets/faculty/KT05-1.webp","alt":"陌生链接、屏幕共享和远程控制配图 1","credit":"情景示意"},{"src":"assets/faculty/KT05-2.webp","alt":"陌生链接、屏幕共享和远程控制配图 2","credit":"情景示意"},{"src":"assets/faculty/KT05-3.webp","alt":"陌生链接、屏幕共享和远程控制配图 3","credit":"情景示意"},{"src":"assets/faculty/KT05-4.webp","alt":"陌生链接、屏幕共享和远程控制配图 4","credit":"情景示意"}],"quiz":{"question":"接到自称客服的电话，称订单有问题要退款，让你点击陌生链接并开启屏幕共享配合操作，正确做法是？","choices":["按对方要求点链接、开共享，尽快完成退款 ","挂断电话，通过官方平台客服核实情况"],"answer":1,"explain":"选 B。陌生链接可能植入木马病毒，开启屏幕共享会泄露支付密码、银行卡信息，正规客服不会要求开启远程控制和屏幕共享，办理相关业务务必通过官方渠道核实。"},"source":"","sourceName":"无","author":"王皓","reviewer":"鄢凡翕","reviewStatus":"已审核","approvalBasis":"项目负责人于2026-10-15确认全部审核完成","sourceSha256":"6422fa8cc8d18b14e932f91f7f9592d76fa3ea835e88076cb82e269ffe520ccd"},{"id":"LJ01","kind":"LJ","title":"涉嫌诈骗时联系公安机关","summary":"当公民遭遇疑似虚构事实、隐瞒真相、诱导转账的诈骗行为时，可通过拨打110或就近派出所报案的方式启动公权力维权","sections":[{"heading":"适用的问题类型","text":"存在虚构身份、虚假投资养老项目、保健品理财、冒充公检法等欺骗行为，被害人已经转账或者即将转账，涉嫌电信网络诈骗、集资诈骗等违法犯罪，有财产受损风险的情形。"},{"heading":"先确认的条件","text":"1，存在虚构事实、隐瞒真相的欺骗行为，对方具有非法占有财产的嫌疑；2，已经发生资金交付，或者马上要进行转账操作；3，留存聊天记录、转账凭证、对方账号、宣传材料等初步证据；4，不属于单纯民事欠款、合同履约纠纷。"},{"heading":"第一步","text":"联系谁 /为什么/ 需要什么材料\n1.联系谁：就近派出所，或直接拨打110\n2.为什么：公安机关可紧急启动资金止付、冻结涉案账户，开展立案侦查，是诈骗案件紧急止损的首选渠道\n3.需要材料：本人身份证；转账截图、银行流水；微信/短信聊天记录、对方联系方式、宣传话术、APP截图等全部证据。"},{"heading":"第二步","text":"第一步未解决时联系谁 / 适用条件\n1.联系谁：办案单位法制部门、12389公安机关警务督察平台；涉案资金紧急问题可同步联系96110反诈专线\n2.适用条件：报案后没有立案、久久得不到反馈，或者对不予立案决定不服；资金止付、冻结存在异议。"},{"heading":"第三步","text":"哪些情况需专业人员进一步评估\n介于民事纠纷与诈骗犯罪边界模糊的案件，例如：养老项目投资、熟人介绍理财、预付保健品款项等，难以区分是正常经营营销还是虚构项目诈骗；报案后公安作出不予立案决定，需要评估是否可以走民事起诉、检察监督救济。"},{"heading":"紧急情形如何分流","text":"1.正在转账、尚未汇出资金：立刻拨打96110反诈劝阻专线或110紧急劝阻止损；2.资金已转出：立刻110报警，就近到派出所做笔录申请止付冻结；人身同时受到威胁，优先处置人身安全。"},{"heading":"不适用或不属于该机构职责的情形","text":"单纯民间借贷、恋爱赠与、合同违约、消费服务纠纷等情形，没有虚构事实骗取财物的行为，属于民事争议"},{"heading":"具体渠道及官方核验来源","text":"①110全国报警电话；②线下辖区派出所；③96110反诈预警劝阻专线；④12389公安督察举报平台。核验来源：公安部反诈中心、全国公安政务服务平台。"},{"heading":"费用、期限等是否因地区或个案而异","text":"报案、侦查不向当事人收取费用；办案期限、资金追回进度受涉案金额、资金跨境/拆分流转、案件复杂程度、地区办案资源影响，个案差异很大。"},{"heading":"该路径与其他路径的衔接和区别","text":"公安路径属于刑事/治安救济，核心是紧急止付、侦查追赃；区别于民事诉讼（无紧急止付，向法院起诉返还财产）；公安不予立案时，可衔接民事诉讼或者向检察院申请立案监督。"}],"images":[{"src":"assets/faculty/LJ01-1.webp","alt":"涉嫌诈骗时联系公安机关配图 1","credit":"情景示意"},{"src":"assets/faculty/LJ01-2.webp","alt":"涉嫌诈骗时联系公安机关配图 2","credit":"情景示意"}],"quiz":null,"source":"","sourceName":"无","author":"鄢凡翕","reviewer":"周渝洁","reviewStatus":"已审核","approvalBasis":"项目负责人于2026-10-15确认全部审核完成","sourceSha256":"3d602456b7e0dd96eaa2bad0c434d7bc3380778f5ca396a0684b59189e5ac7fa"},{"id":"LJ02","kind":"LJ","title":"消费纠纷投诉、调解与民事诉讼","summary":"老年人购买养老产品、保健品等发生消费争议，可先向市场监管部门投诉，或者进行调解，调解不成的，可以向人民法院提起民事诉讼主张退款、赔偿。","sections":[{"heading":"适用的问题类型","text":"老年人购买保健品、养老服务、康养产品等，遭遇虚假宣传、产品质量缺陷、价格欺诈、商家拒不退款等消费争议。"},{"heading":"先确认的条件","text":"1，存在消费买卖/服务合同；2，经营者存在违约或者侵害消费者权益行为；3，保留付款凭证、宣传资料、产品实物、沟通记录；4，没有超过诉讼时效。"},{"heading":"第一步","text":"联系谁/为什么/需要什么材料\n联系谁：市场监督管理部门/12315平台\n为什么：市场监管部门可依法受理消费者投诉，对经营者进行调查、督促和行政调解，是消费纠纷初期维权的常用渠道。\n需要什么材料：1，本人身份证；2，订单、合同、收据、付款凭证；3，产品照片、宣传材料；4，与商家的沟通记录；5，商家名称、地址、联系方式等信息。"},{"heading":"第二步","text":"第一步未解决时联系谁/适用条件\n联系谁：市场监管部门、消协、人民调解组织（开展调解）；调解失败后，向基层人民法院提起民事诉讼\n适用条件：1，12315投诉受理后，商家拒绝协商、双方无法达成一致；2，事实清楚、证据基础完备，希望通过第三方居中协商；3，行政调解仍无法解决争议，需要法院裁判来强制保障退款或赔偿。"},{"heading":"第三步","text":"哪些情况需专业人员进一步评估：\n1.证据不足，只有口头约定，缺少合同、付款凭证，难以认定消费关系、违约事实；\n2.商家已经注销、无财产，需要评估胜诉后执行回款的可能性；\n3.案件同时涉嫌消费欺诈刑事犯罪，需要区分走民事维权，还是移交公安报案；\n4.不确定诉讼时效、赔偿项目、起诉管辖法院；\n5.老年当事人经济困难、行动不便，评估是否可以申请法律援助、检察支持起诉。"},{"heading":"紧急情形如何分流","text":"商家还在持续虚假宣传，立即12315投诉要求查处；商家转移财产，可在起诉时同步申请财产保全。"},{"heading":"不适用或不属于该机构职责的情形","text":"个人私下交易、股权投资理财纠纷、不属于生活消费的经营采购；市场监管无强制判决、强制执行权力。\n具体渠道：12315小程序/热线、市场监管局、基层人民法院"},{"heading":"费用、期限等是否因地区或个案而异","text":"12315投诉调解免费；法院起诉需要预交案件受理费，胜诉后一般由对方承担；调解、审理周期受案情、地区差异影响。"},{"heading":"该路径与其他路径的衔接和区别","text":"本路径是民事消费救济；区别于公安报案（公安处理刑事诈骗）；如果发现经营者涉嫌诈骗犯罪，可以从民事路径转向公安报案。"}],"images":[{"src":"assets/faculty/LJ02-1.webp","alt":"消费纠纷投诉、调解与民事诉讼配图 1","credit":"情景示意"},{"src":"assets/faculty/LJ02-2.webp","alt":"消费纠纷投诉、调解与民事诉讼配图 2","credit":"情景示意"},{"src":"assets/faculty/LJ02-3.webp","alt":"消费纠纷投诉、调解与民事诉讼配图 3","credit":"情景示意"}],"quiz":null,"source":"","sourceName":"无","author":"鄢凡翕","reviewer":"周渝洁","reviewStatus":"已审核","approvalBasis":"项目负责人于2026-10-15确认全部审核完成","sourceSha256":"450956faa9fd60f9be7c44e566f9145a920efb7ba64faacf9d83dfcaac7ff6c1"},{"id":"LJ03","kind":"LJ","title":"法律援助、社会组织和志愿服务","summary":"经济困难的老年受害者，可向法律援助中心申请免费法律帮助；也可求助老龄社会组织、法律志愿团队，获取法律咨询、文书协助。","sections":[{"heading":"适用的问题类型","text":"老年人遭遇诈骗、消费侵权等财产损害，经济困难，无力自行聘请律师，需要法律咨询、代写文书、代理案件。"},{"heading":"先确认的条件","text":"1，案件属于法律援助受理范围；2，申请人符合当地经济困难认定标准；3，持有案件基础证据。"},{"heading":"第一步","text":"联系谁 /为什么/ 需要什么材料\n联系：12348公共法律服务热线、属地法律援助中心；\n为什么：可免费提供法律咨询、代写法律文书、指派援助律师；\n材料：身份证、年龄证明、经济困难证明、案件相关证据材料。"},{"heading":"第二步","text":"第一步未解决时联系谁 / 适用条件\n对不予法律援助决定不服，向同级司法行政机关提出异议；适用条件：提交援助申请被驳回。"},{"heading":"第三步","text":"哪些情况需专业人员进一步评估\n难以判断案件是否属于援助范围；不确定经济困难证明材料是否达标；案件同时涉及民事、刑事多条维权渠道，需要整体方案规划。"},{"heading":"紧急情形如何分流","text":"紧急止付、人身危险优先联系公安；诉讼时效即将届满的，优先联系法律援助中心加急申请。"},{"heading":"不适用或不属于该机构职责的情形","text":"不属于法定法律援助案件范围；不符合经济困难条件；法律援助不负责资金追回、案件胜诉担保。\n具体渠道：12348公共法律服务热线、各地法律援助中心、老龄协会、高校法律志愿团队等\n费用：免费"},{"heading":"该路径与其他路径的衔接和区别","text":"本路径是法律服务支持路径，不直接解决纠纷，为公安报案、民事诉讼、检察监督提供法律协助。"}],"images":[{"src":"assets/faculty/LJ03-1.webp","alt":"法律援助、社会组织和志愿服务配图 1","credit":"情景示意"},{"src":"assets/faculty/LJ03-2.webp","alt":"法律援助、社会组织和志愿服务配图 2","credit":"情景示意"},{"src":"assets/faculty/LJ03-3.webp","alt":"法律援助、社会组织和志愿服务配图 3","credit":"情景示意"}],"quiz":null,"source":"","sourceName":"无","author":"鄢凡翕","reviewer":"周渝洁","reviewStatus":"已审核","approvalBasis":"项目负责人于2026-10-15确认全部审核完成","sourceSha256":"31282cc0903d942386f284d593c24e9f97b71b029587b738cdc420379c3802a7"},{"id":"LJ04","kind":"LJ","title":"检察支持起诉与公益诉讼线索","summary":"老年人遭受养老诈骗、消费侵害等，无力起诉的，可以向检察院申请支持起诉；群体性侵害老年人财产权益的案件，可以作为公益诉讼线索提交检察机关。","sections":[{"heading":"适用的问题类型","text":"养老诈骗、虚假养老产品销售等侵害老年群体财产权益；老年人弱势、取证困难，无法独立起诉；侵害众多老年人公共利益的案件。"},{"heading":"先确认的条件","text":"1，存在侵害老年人财产权益的事实；2，老年人存在诉讼困难（无能力起诉、取证难）；群体性案件损害社会公共利益；3，已经留存基础证据。"},{"heading":"第一步","text":"联系谁 /为什么/ 需要什么材料\n联系12309检察服务中心、属地人民检察院；\n为什么：检察院可对个案支持起诉，对群体性养老侵害线索开展公益诉讼调查；\n材料：身份证、案件证据、公安/市场监管处理记录、受害情况说明。"},{"heading":"第二步","text":"第一步未解决时联系谁 / 适用条件\n对检察院不予受理决定不服，可以向上一级检察院申请复查；\n适用条件：提交支持起诉/公益诉讼线索不予受理。"},{"heading":"第三步","text":"哪些情况需专业人员进一步评估\n区分是个案维权还是群体性公益损害；评估是否同时存在刑事犯罪，判断优先走刑事报案还是检察支持起诉。"},{"heading":"紧急情形如何分流","text":"无"},{"heading":"不适用或不属于该机构职责的情形","text":"单纯私人债务纠纷；个案完全具备起诉能力、不存在弱势困境；检察院不直接替当事人追回钱款。"},{"heading":"具体渠道及官方核验来源","text":"12309检察服务热线、各级人民检察院"},{"heading":"费用、期限等是否因地区或个案而异","text":"提交线索、申请支持起诉全程免费；审查周期取决于案件复杂程度，各地办案节奏不同。"},{"heading":"该路径与其他路径的衔接和区别","text":"检察路径属于法律监督、支持起诉/公益救济；可以衔接公安立案监督、民事诉讼。"}],"images":[{"src":"assets/faculty/LJ04-1.webp","alt":"检察支持起诉与公益诉讼线索配图 1","credit":"情景示意"}],"quiz":null,"source":"","sourceName":"无","author":"鄢凡翕","reviewer":"周渝洁","reviewStatus":"已审核","approvalBasis":"项目负责人于2026-10-15确认全部审核完成","sourceSha256":"161c1ae3c3bfb239ad1f92079266aca68d5c10a2e09e79b70cdfa6bb5cc1bf19"},{"id":"QA01","kind":"QA","title":"怀疑钱被骗了，先做什么","summary":"当公民是诈骗行为时，先不要再继续转账、不要透露银行卡密码、验证码，立刻留存证据，尽快报警。","sections":[{"heading":"一句直接回应","text":"先不要再继续转账、不要透露银行卡密码、验证码，立刻留存证据，尽快报警。"},{"heading":"一般处理步骤","text":"停止所有操作：不再转账，不泄露验证码、银行卡密码。\n保存全部证据：聊天记录、通话录音、转账凭证、对方账号。\n马上报警，同时联系银行冻结账户 / 止付。"},{"heading":"需要准备的材料","text":"- 转账记录、银行流水、付款截图\n- 和对方的聊天记录、短信、通话录音\n- 对方微信号、手机号、收款账号、网址\n- 本人身份证、银行卡"},{"heading":"还需要核实哪些事实","text":"是什么事由转钱（中奖、投资、治病、公检法办案、熟人借钱等）\n转账时间、金额、收款账户信息\n是否还能联系上对方，对方有没有继续要求打钱\n是否已经点击陌生链接、安装陌生 APP、泄露验证码"},{"heading":"不适用情形","text":"属于正常民事经济纠纷（民间借贷、合同货款争议，不属于诈骗）\n钱款尚未转出，只是单纯担心风险，没有实际资金损失\n家庭亲属之间金钱矛盾，不存在第三方诈骗行为"},{"heading":"何时需要联系专业人员或线下机构","text":"已经转出资金，怀疑电信网络诈骗 → 立刻去就近派出所报案；同步联系开户行申请止付\n对方持续诱导转账、威胁恐吓老人 → 立即报警\n老人情绪激动、意识不清，无法完整陈述事情经过 → 通知家属陪同前往派出所"},{"heading":"引用依据","text":"依据《中华人民共和国刑法》关于诈骗罪规定、《电信网络诈骗案件办理指引》：“怀疑被骗，停止转账、留存证据、及时报警，是首要处置方式。”"}],"images":[],"quiz":null,"source":"","sourceName":"无","author":"周渝洁","reviewer":"鄢凡翕","reviewStatus":"已审核","approvalBasis":"项目负责人于2026-10-15确认全部审核完成","sourceSha256":"d4acb02e57f9903235eabbf308aefb252d9abb2f976e7fabee9953252a63fe61"},{"id":"QA02","kind":"QA","title":"转账后应保存什么材料","summary":"转账后需完整留存转账凭证、对方信息、聊天通话记录及本人证件，切勿删除电子记录，以备报案核查，但保存材料不代表钱款一定能追回。","sections":[{"heading":"先给一句直接回应","text":"转账后所有和这次交易、对方沟通相关的信息都不要删除，全部截图或者纸质留存，方便后续报案核查。"},{"heading":"一般处理步骤","text":"1. 立即截图保存全部记录，不要删除聊天、短信、通话信息。\n2. 打印银行 / 支付软件转账凭证，记下对方账号、联系方式。\n3. 将材料整理好，交由家属保管，以备报警使用。"},{"heading":"需要准备的材料","text":"1. 转账凭证：转账截图、支付订单号、银行回执单、银行卡流水\n2. 对方信息：对方手机号、微信号、QQ 号、收款账户、姓名\n3. 沟通记录：微信 / 短信聊天记录、通话录音、对方发来的图片、链接、APP 安装包\n4. 身份材料：本人身份证、转出资金所用银行卡"},{"heading":" 还需要核实哪些事实","text":"1. 转账渠道：银行卡、微信、支付宝还是其他平台\n2. 有没有点击陌生链接、下载对方提供的 APP\n3. 是否删除过聊天记录、通话记录\n4. 有没有向对方提供过验证码、银行卡密码"},{"heading":"不适用情形","text":"1. 没有实际转账，仅咨询准备转账要保存什么\n2. 交易是正规线下消费，不存在被骗风险，仅普通购物转账\n3. 记录已经全部删除，无法找回电子信息"},{"heading":"何时需要联系专业人员或线下机构","text":"1. 怀疑被骗，整理好材料后尽快到派出所报案\n2. 电子记录误删除，需要调取银行 / 支付平台交易凭证，联系银行或支付平台客服\n3. 材料繁多、老人无法整理，让家属协助，必要时到线下网点打印流水"},{"heading":"引用依据对应哪一句结论","text":"依据电信网络诈骗案件取证相关要求：“转账相关交易凭证、与嫌疑人的通讯记录，是报案和案件调查的重要证据材料，应当完整留存。”"}],"images":[],"quiz":null,"source":"","sourceName":"无","author":"周渝洁","reviewer":"鄢凡翕","reviewStatus":"已审核","approvalBasis":"项目负责人于2026-10-15确认全部审核完成","sourceSha256":"6bc61d228037da461db75f0ae36a035589c6d38b8e215d7e083e50d737025aaf"},{"id":"QA03","kind":"QA","title":"网购未收到商品怎么办","summary":"网购没收到货先查物流联系商家，协商不成在平台申请售后，保存订单等凭证；平台解决不了可打 12315，私下转账不发货涉嫌诈骗可报警，但不能保证一定退款。","sections":[{"heading":"先给一句直接回应","text":"先查询物流信息，优先联系商家沟通；协商不成，在平台发起售后申请，保留好订单、付款凭证。"},{"heading":"一般处理步骤","text":"1. 查看订单物流信息，联系商家核实发货、包裹情况。\n2. 协商无果，在购物平台提交售后，申请退款或补发。\n3. 商家拒不处理，向平台客服投诉；仍无法解决可拨打 12315 维权。"},{"heading":" 需要准备的材料","text":"- 网购订单截图、付款记录\n- 物流信息截图、快递单号\n- 和商家聊天记录\n- 商品宣传页面截图"},{"heading":"还需要核实哪些事实","text":"1. 是哪个购物平台下单（淘宝 / 抖音 / 拼多多等）\n2. 物流显示什么状态：待发货、运输中、已签收还是丢失\n3. 付款渠道：平台内支付，还是私下微信 / 银行卡转账\n4. 商家是否还能联系上，有没有承诺发货时间"},{"heading":"不适用情形","text":"1. 已正常签收，只是开箱后商品不满意、有破损（属于收货后质量纠纷）\n2. 私下脱离平台转账交易，没有平台订单（不属于正规平台网购）\n3. 物流显示已签收，包裹放在快递柜 / 驿站，本人还未去取件"},{"heading":"何时需要联系专业人员或线下机构","text":"1. 平台介入后商家仍然拒绝退款、失联，拨打 12315 向市场监管部门投诉\n2. 脱离平台私下转账付款，商家收钱不发货，涉嫌诈骗，及时报警\n3. 老人不会操作线上售后，可请家属协助办理维权"},{"heading":"引用依据","text":"依据《消费者权益保护法》：经营者收取货款后未按约定交付商品，消费者有权要求经营者履行交付商品义务或者退款。"}],"images":[],"quiz":null,"source":"","sourceName":"无","author":"周渝洁","reviewer":"鄢凡翕","reviewStatus":"已审核","approvalBasis":"项目负责人于2026-10-15确认全部审核完成","sourceSha256":"2b9d294b54168c85ba9202fd2e4825330a291652c5eadf743a2bf2a57f0b1d63"},{"id":"QA04","kind":"QA","title":"养老理财无法提现怎么办","summary":"养老理财无法提现先看合同锁定期，联系持牌机构客服核实原因并留存全套证据，协商不成拨打 12378 投诉；陌生 APP、要求交解冻费、平台失联则涉嫌诈骗，尽快报警，但无法保证资金一定追回。","sections":[{"heading":"先给一句直接回应","text":"先查看理财合同，联系发行机构客服核实是产品锁定期限还是平台异常，保存全部材料；正规产品向 12378 投诉，疑似非法集资或诈骗立刻报警。"},{"heading":"一般处理步骤","text":"1. 核对产品合同，联系理财 / 银行官方客服，查清不能提现的原因。\n2. 机构推诿不处理，拨打 12378 向金融监管部门投诉。\n3. 发现是虚假平台、非法集资，保留证据马上报警。"},{"heading":"需要准备的材料","text":"- 理财合同、风险告知书、产品宣传资料\n- 转账记录、银行流水、充值截图\n- APP 截图、账户页面、客服聊天记录、通话录音\n- 本人身份证、购买理财所用银行卡"},{"heading":"还需要核实哪些事实","text":"1. 是否在银行、持牌理财公司购买，还是不知名 APP 平台\n2. 产品是否还在封闭锁定期，合同约定赎回规则是什么\n3. 对方是否要求缴纳解冻费、保证金才能提现\n4. 平台能否正常登录，客服是否失联"},{"heading":" 不适用情形","text":"1. 产品还在封闭期，按合同约定本来就不能提前赎回（属于正常产品规则）\n2. 本人忘记交易密码、银行卡冻结导致无法收款，不是理财不能赎回\n3. 只是担心以后取不出钱，目前还没有申请提现"},{"heading":"何时需要联系专业人员或线下机构","text":"1. 正规持牌机构理财，机构拒绝按合同办理赎回，拨打 12378 金融监管投诉\n2. 平台失联、要求交解冻费、非持牌机构，涉嫌非法集资 / 诈骗，立即到派出所报警\n3. 老人看不懂合同、不会和机构沟通，请家属陪同到银行网点处理"},{"heading":"引用依据","text":"依据《银行业保险业消费投诉处理管理办法》、国家金融监管总局养老理财风险提示：“金融消费者与持牌机构理财纠纷，可向机构投诉、监管部门反映；虚假养老理财平台涉嫌非法集资诈骗，应当报警”"}],"images":[],"quiz":null,"source":"","sourceName":"无","author":"周渝洁","reviewer":"鄢凡翕","reviewStatus":"已审核","approvalBasis":"项目负责人于2026-10-15确认全部审核完成","sourceSha256":"ac3c14e41d544aae7402d210c3d019ab03a22cc5c2741d5a8fbdd17891c1b3ad"},{"id":"QA05","kind":"QA","title":"保健品纠纷如何投诉","summary":"保健品纠纷先收集票据、宣传录音、产品包装等证据，优先与商家协商退款，协商不成拨打 12315 向市场监管部门投诉；商家跑路、涉嫌传销诈骗则报警，但无法保证一定退款或拿到赔偿。","sections":[{"heading":"先给一句直接回应","text":"先保留全部证据，优先和商家协商退款；协商不成拨打 12315 投诉，若对方涉嫌诈骗、传销，直接报警。"},{"heading":"一般处理步骤","text":"1. 收集保存购买凭证、产品包装、宣传资料、沟通录音等全部证据。\n2. 先联系销售商家协商退货退款。\n3. 协商无果拨打 12315 向市场监管部门投诉；涉嫌诈骗、非法传销的立即报警。"},{"heading":"需要准备的材料","text":"- 购买凭证：小票、订单截图、转账记录、付款流水\n- 产品实物、包装盒、说明书、保健食品批准文号页面\n- 宣传材料：宣传单、讲座录音、视频、聊天记录、直播录屏（重点保存宣称治病的内容）\n- 商家信息：店铺名称、地址、销售人员联系方式\n- 本人身份证"},{"heading":"还需要核实哪些事实","text":"1. 购买渠道：线下会场 / 门店、抖音 / 直播间、上门推销还是私下微信购买\n2. 商家有没有宣称保健品可以治病、替代药品\n3. 是否有产品质量问题、食用后身体不适\n4. 商家现在是否还能联系上"},{"heading":"不适用情形","text":"1. 单纯个人食用后主观感觉无效，商家无虚假宣传、无质量问题\n2. 已经经过法院、市场监管部门处理完毕的同一纠纷\n3. 不是生活消费购买，用于批量经营进货\n4. 超出法定维权时效且无特殊理由"},{"heading":"何时需要联系专业人员或线下机构","text":"1. 商家拒不协商退款、存在虚假宣传，拨打 12315 或到当地市场监管所现场投诉\n2. 商家跑路、上门洗脑推销、涉嫌传销或诈骗，立即到派出所报警\n3. 食用保健品出现身体损伤，保留就医病历，可同步投诉并咨询法律维权"},{"heading":"引用依据","text":"依据《消费者权益保护法》《市场监督管理投诉举报处理办法》：**保健品消费纠纷可通过 12315 向市场监管部门投诉；经营者虚假宣传、欺诈侵害消费者权益，消费者可主张退款，涉嫌犯罪由公安处理**中国政府网。"}],"images":[],"quiz":null,"source":"","sourceName":"无","author":"周渝洁","reviewer":"鄢凡翕","reviewStatus":"已审核","approvalBasis":"项目负责人于2026-10-15确认全部审核完成","sourceSha256":"a5a8365351ce7ac6cbf1e1bedbeea9d0c8ca218c47fbc3e16fe15ef7458304b6"},{"id":"QA06","kind":"QA","title":"如何申请法律援助","summary":"申请法律援助先拨打 12348 咨询案件范围，准备身份证件、纠纷证据与经济困难材料提交法律援助中心，审核通过会指派免费律师，但不保证案件胜诉或拿到赔偿。","sections":[{"heading":"先给一句直接回应","text":"先拨打 12348 公共法律服务热线咨询，确认案件符合范围、满足经济困难条件，携带材料到当地法律援助中心提交申请。"},{"heading":"一般处理步骤","text":"1. 拨打 12348 热线咨询，确认案件是否属于法律援助受理范围。\n2. 准备身份证、案件材料、经济困难证明，前往法律援助中心提交申请。\n3. 等待审核，审核通过后指派援助律师。"},{"heading":"需要准备的材料","text":"- 本人身份证等身份证明；委托代办的，准备代办人身份证件\n- 法律援助申请表（窗口工作人员可帮忙填写）\n- 经济困难相关证明材料（低保、特困证明或经济困难承诺书，部分情形免核查）\n- 案件相关材料：合同、转账凭证、病历、欠条、纠纷证据等"},{"heading":"还需要核实哪些事实","text":"1. 是什么类型的纠纷（赡养、侵权、被骗、劳动纠纷等）\n2. 申请人年龄，是否低保、特困、残疾人等免经济核查人群\n3. 是否已经委托其他律师\n4. 案件目前处于协商、调解还是法院诉讼阶段"},{"heading":"不适用情形","text":"1. 不属于法定法律援助案件范围（如普通商事投资纠纷）\n2. 经济条件不符合标准，且不属于免经济困难核查情形\n3. 已经自行聘请律师代理案件\n4. 诉求明显违法、没有事实和法律依据"},{"heading":"何时需要联系专业人员或线下机构","text":"1. 想先了解是否符合条件，拨打 12348 公共法律服务热线\n2. 确认符合条件，携带材料到当地法律援助中心线下提交申请\n3. 行动不便老人，可咨询是否支持邮寄、线上申请或上门协助"},{"heading":"引用依据","text":"依据《中华人民共和国法律援助法》：**经济困难公民，法定案件范围内可申请免费法律援助；符合法定特殊情形，无需核查经济困难状况**。"}],"images":[],"quiz":null,"source":"","sourceName":"无","author":"周渝洁","reviewer":"鄢凡翕","reviewStatus":"已审核","approvalBasis":"项目负责人于2026-10-15确认全部审核完成","sourceSha256":"5820fd3d566d71b4bc4523f8de611b3b2a1a28b68da1aec6141d13f5ace4e6d6"},{"id":"QA07","kind":"QA","title":"诉讼费能否缓交、减交或免交","summary":"经济困难交不起诉讼费，可在立案或上诉时向法院提交书面申请与困难证明，申请缓交、减交，自然人可申请免交，由法院审核决定，但诉讼费减免不代表案件一定胜诉。","sections":[{"heading":"先给一句直接回应","text":"经济困难交纳诉讼费确有困难，可以向受理案件的法院申请缓交、减交、免交（免交仅限自然人），在起诉或上诉时提交书面申请和经济困难证明，由法院审核决定。"},{"heading":"一般处理步骤","text":"1. 准备书面申请书、经济困难证明，在起诉或上诉立案时一并提交法院。\n2. 等待法院审查，法院会作出准予或者不予救助的书面决定。\n3. 获批后按决定要求执行；未获批，按法院通知按时交纳诉讼费。"},{"heading":"需要准备的材料","text":"- 诉讼费司法救助书面申请书（法院窗口可拿模板）\n- 本人身份证\n- 经济困难证明：低保证、特困证明、村委会 / 社区、民政出具的困难证明\n- 案件相关证据材料（起诉状、证据复印件等）"},{"heading":"还需要核实哪些事实","text":"1. 案件类型（赡养、侵权、合同纠纷等）\n2. 是否属于低保、特困、残疾人无固定收入等情形\n3. 是立案起诉阶段，还是上诉阶段\n4. 是否已经申请法律援助"},{"heading":"不适用情形","text":"1. 不符合经济困难标准，无困难证明材料\n2. 免交不适用于企业、单位（免交仅自然人）\n3. 申请时间超出起诉、上诉阶段，且无正当理由\n4. 案件明显没有法律依据、恶意诉讼"},{"heading":"何时需要联系专业人员或线下机构","text":"1. 准备立案时，直接到受理法院立案庭提交司法救助申请\n2. 不清楚条件、不会写申请书，拨打 12348 公共法律服务热线咨询"},{"heading":"引用依据","text":"依据《诉讼费用交纳办法》第 44 条：**当事人交纳诉讼费用确有困难的，可以向人民法院申请缓交、减交或者免交诉讼费用的司法救助；诉讼费用的免交只适用于自然人**"}],"images":[],"quiz":null,"source":"","sourceName":"无","author":"周渝洁","reviewer":"鄢凡翕","reviewStatus":"已审核","approvalBasis":"项目负责人于2026-10-15确认全部审核完成","sourceSha256":"d278b4f1dac03767f8cee8f955beae874b59737671b0c5ca39e0a8652d84cb39"},{"id":"QA08","kind":"QA","title":"子女协助诉讼需要什么手续","summary":"委托子女协助诉讼需签署授权委托书，备好双方身份证与亲子关系证明提交法院，区分一般授权与和解、撤诉等特别授权；离婚等案件老人原则上仍需本人出庭，子女代理不能保证胜诉。","sections":[{"heading":"先给一句直接回应","text":"让子女作为近亲属代理诉讼，需要签署授权委托书，准备双方身份证、亲属关系证明，一并提交给受理案件的法院，分清一般授权和特别授权。"},{"heading":"一般处理步骤","text":"1. 签署授权委托书，写明委托事项与权限（一般授权或特别授权）。\n2. 准备双方身份证复印件、亲属关系证明。\n3. 将全套材料提交法院立案庭 / 承办法官，完成委托登记。"},{"heading":"需要准备的材料","text":"1. 授权委托书：老人亲笔签名，写明委托权限；涉及承认诉求、和解、撤诉、上诉等重大事项要单独注明特别授权\n2. 老人（委托人）身份证原件及复印件。\n3. 子女（代理人）身份证原件及复印件。\n4. 亲属关系证明：户口本、出生证明、派出所出具的亲属关系证明等。\n5. 案件材料：起诉状、证据材料复印件。"},{"heading":"还需要核实哪些事实","text":"1. 案件类型（赡养、合同、侵权等）\n2. 子女是仅帮忙递交材料，还是要代为开庭、调解、和解\n3. 是否需要特别授权（撤诉、变更请求、和解、上诉等）\n4. 案件当前阶段：立案、审理、上诉还是执行"},{"heading":" 不适用情形","text":"1. 子女存在法律规定不能担任代理人的情形\n2. 离婚案件，老人本人不能表达意志之外，仍需要本人出庭，子女不能单独全权代理\n3. 没有亲属关系证明，无法证实亲子关系\n4. 委托事项违法"},{"heading":"何时需要联系专业人员或线下机构","text":"1. 不清楚授权委托书怎么写、分不清一般 / 特别授权，拨打 12348 咨询或到法院立案窗口拿模板\n2. 案件复杂，建议同时咨询法律援助或委托律师\n3. 亲属关系证明难以调取，到派出所、户籍地社区咨询开具材料"},{"heading":"引用依据","text":"依据《民事诉讼法》第 61、62 条：**当事人可以委托近亲属作为诉讼代理人，必须向法院提交委托人签名的授权委托书、代理人身份证明及亲属关系证明；代为和解、放弃诉求等事项，需要特别授权**"}],"images":[],"quiz":null,"source":"","sourceName":"无","author":"周渝洁","reviewer":"鄢凡翕","reviewStatus":"已审核","approvalBasis":"项目负责人于2026-10-15确认全部审核完成","sourceSha256":"7e470f8a11ae8f0b1b52b0249ed3676d7a3ff88df14f51935b3bcf337e0bf6fb"},{"id":"QA09","kind":"QA","title":"个人发现公益损害如何提供线索","summary":"个人发现公益损害，先留存现场照片视频并记录时间地点，通过 12309 热线、检察网或检察院现场提交线索，由检察院公益诉讼部门核查，但不保证线索一定立案或者问题彻底整改。","sections":[{"heading":"先给一句直接回应","text":"发现损害社会公共利益的情形，可通过 12309 热线、12309 中国检察网或 “益心为公” 平台提交线索，写明地点、事实，附上照片视频证据，由检察院公益诉讼部门核查。"},{"heading":"一般处理步骤","text":"1. 固定证据，记录事发地点、时间，拍摄现场照片、视频。\n2. 通过 12309 热线、线上平台或到当地检察院现场提交线索。\n3. 检察院登记分流、核查，实名提交的会反馈办理进展。"},{"heading":"需要准备的材料","text":"- 线索说明：写明事发地点、时间、违法事实、造成的公益损害后果\n- 证据材料：现场照片、视频、录音、相关公告、单据\n- 举报人信息（实名举报建议留存姓名、联系电话；也可匿名）\n- 相关文件：如新闻报道、检测材料、现场标识照片等"},{"heading":"还需要核实哪些事实","text":"1. 损害发生的具体地点、持续时间\n2. 属于哪个领域：生态环境、食品药品安全、国有财产、英烈保护等\n3. 是否已经向城管、市场监管等行政部门反映过，处理情况如何\n4. 是否存在人身安全风险，现场是否危险"},{"heading":"不适用情形","text":"1. 仅个人之间民事纠纷，不涉及社会公共利益\n2. 线索信息模糊、没有具体地点、无任何证据，无法核查\n3. 不属于检察公益诉讼受理范围，应当由其他主管部门直接处理\n4. 捏造、虚构事实恶意举报"},{"heading":"何时需要联系专业人员或线下机构","text":"1. 准备提交线索，拨打 12309 检察服务热线咨询\n2. 不会线上提交，直接前往当地检察院 12309 服务中心现场反映\n3. 情况紧急、存在重大安全隐患，可同步拨打对应行政部门或 110"},{"heading":"引用依据","text":"依据《人民检察院公益诉讼办案规则》第 24 条：“公民发现损害国家利益、社会公共利益行为，可向人民检察院提交公益诉讼线索，检察院登记后开展核查处理。”"}],"images":[],"quiz":null,"source":"","sourceName":"无","author":"周渝洁","reviewer":"鄢凡翕","reviewStatus":"已审核","approvalBasis":"项目负责人于2026-10-15确认全部审核完成","sourceSha256":"50799429151ca6fcd65ada6b306aa4d29d47d83599f50109e6c412765881c215"},{"id":"QA10","kind":"QA","title":"支持起诉与公益诉讼有什么区别","summary":"支持起诉是检察院辅助受害个人当原告起诉，保护个人私益；公益诉讼由法定组织或检察院自己作为原告，保护社会公共利益，个人不能提起公益诉讼，是否受理由检察院审查决定。","sections":[{"heading":"先给一句直接回应","text":"支持起诉是检察院帮助**受侵害的个人**去起诉，原告是当事人本人；公益诉讼是检察院或法定组织**自己作为原告起诉**，目的保护社会公共利益，个人不能直接提起公益诉讼。"},{"heading":"一般处理步骤","text":"1. 判断是个人权益受损（赡养、欠款等）还是环境、食品等公共利益受损。\n2. 个人受害、自己想起诉但能力不足，可向检察院申请支持起诉。\n3. 损害众多人公共利益，可提交线索，由法定组织或检察院提起公益诉讼。"},{"heading":"需要准备的材料","text":"- 支持起诉：本人身份证、受损证据、想维权的书面说明\n- 公益诉讼线索：事发地点、时间、照片视频、损害事实材料\n- 两类都可以准备：沟通记录、票据、现场证据"},{"heading":"还需要核实哪些事实","text":"1. 是**您个人权益受损**，还是很多群众共同的公共利益受损\n2. 您本人有没有起诉意愿，是否行动不便、不懂诉讼\n3. 属于赡养、欠薪、人身损害，还是污染环境、伪劣食品等领域\n4. 是否已经向其他部门反映过"},{"heading":"不适用情形","text":"1. 个人私益纠纷，直接要求检察院提起公益诉讼（个人不能启动公益诉讼）\n2. 公共利益损害，但无任何线索、无具体事实，无法核查\n3. 当事人本人不愿意起诉，却要求检察院支持起诉\n4. 捏造虚假事实提交材料"},{"heading":"何时需要联系专业人员或线下机构","text":"1. 个人受侵害、想打官司但能力不足，拨打 12309 申请支持起诉\n2. 发现污染、有害食品等损害大众利益，拨打 12309 提交公益诉讼线索\n3. 分不清属于哪一类，拨打 12348 或 12309 咨询"},{"heading":"引用依据","text":"依据《民事诉讼法》第 15 条、第 58 条：**支持起诉是机关、检察院支持受损害个人起诉，原告是受害当事人；公益诉讼由法定机关、组织或检察院作为原告起诉，保护社会公共利益**"}],"images":[],"quiz":null,"source":"","sourceName":"无","author":"周渝洁","reviewer":"鄢凡翕","reviewStatus":"已审核","approvalBasis":"项目负责人于2026-10-15确认全部审核完成","sourceSha256":"98a66b5d8f7697f111571afe8eaa54953ec216fa62eb8e317a5dc9f969afb370"}];
